// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 100 ether);
        vm.assume(amount > 0);

        vm.deal(address(c), amount);

        address owner = address(this);

        uint256 balanceBefore = owner.balance;

        bool ok;
        try c.withdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balanceAfter = owner.balance;

        assertTrue(!ok || balanceAfter > balanceBefore);
    }
}
